const { error } = require('console');
const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _options;

var luaInterfaces = {}



function trimKey(key) {
    // remove file extension from key if have
    return key.replace(/\.[^.]+$/, '');
}


function tryParseDefine(filePath, events) {

    var hasTypeDefine
    var hasNameDefine
    var hasClassCtor
    filePath = filePath.replace(/\\/g, '/');
    var rbxPath = _robloxPathDict.getRbxPath(filePath)

    var key = trimKey(path.basename(filePath))

    const fileContent = fs.readFileSync(filePath, 'utf8');
    if (fileContent.includes('export type Type =')) {
        hasTypeDefine = true
    }
    else if (fileContent.includes(`export type ${key} =`)) {
        hasNameDefine = true
    }
    // 如果 content 含有 `.new(`, 则视为构造函数
    else if (fileContent.split('\n').some(line => line.includes('function') && line.includes('.new('))) {
        hasClassCtor = true
    }
    luaInterfaces[rbxPath] = {
        FilePath: filePath,
        HasTypeDefine: hasTypeDefine,
        HasNameDefine: hasNameDefine,
        Key: key,
        HasClassCtor: hasClassCtor
    }
    if (filePath.endsWith("_extensions.lua")) {
        luaInterfaces[rbxPath].Alias = path.basename(filePath).replace("_extensions.lua", "")
    }
}

function tryParseInterfacesInOneFile(filePath, events) {
    filePath = filePath.replace(/\\/g, '/');
    var rbxPath = _robloxPathDict.getRbxPath(filePath)
    const fileContent = fs.readFileSync(filePath, 'utf8');
    luaInterfaces[rbxPath] = {
        FilePath: filePath,
        UseDirectContent: true,
        DirectContent: fileContent
    }
}



// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath, events) {

    var changed = false
    if (!fs.existsSync(filePath)) {
        return changed
    }


    // get file name
    const fileName = path.basename(filePath);

    if (fileName == ".interfaces.lua") {
        tryParseInterfacesInOneFile(filePath, events);
        return true
    }

    // 如果fileName包含多于一个 ".", 就return
    if (fileName.split('.').length > 2) {
        return changed;
    }

    // 为配置 改版 robloxLsp, 以 .d.lua 结尾的文件,不解析
    if (fileName.endsWith(".d.lua")) {
        return changed;
    }

    if (fileName.startsWith("I") && fileName.endsWith(".lua")) {
        // fileName 第二个字母必须大写
        if (fileName[1] == fileName[1].toUpperCase()) {
            tryParseDefine(filePath, events);
            changed = true
        }
    }

    // if (fileName.endsWith(".luau")) {
    //     tryParseDefine(filePath, events);
    //     changed = true
    // }

    return changed
}

function findAndGenSubfolders(basePath, events) {
    if (_options.isIgnoreFolder(path.resolve(basePath))) return
    var changed = false

    if (!fs.existsSync(basePath)) {
        changed = true
        return false
    }

    const stats = fs.lstatSync(basePath);
    if (stats.isDirectory() || (stats.isSymbolicLink() && fs.statSync(basePath).isDirectory())) {

        for (const item of fs.readdirSync(basePath, { withFileTypes: true })) {

            const fullPath = path.join(basePath, item.name);
            changed |= findAndGenSubfolders(fullPath, events);
        }
    } else {

        changed |= tryGen(basePath, events)
    }
    return changed
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            if (fs.existsSync(key)) {
                changed |= findAndGenSubfolders(key, events)
            } else {
                key = key.replace(/\\/g, '/');
                // foreach
                for (const [_, interfaceData] of Object.entries(luaInterfaces)) {
                    if (interfaceData.FilePath === key) {
                        delete luaInterfaces[_];
                        changed = true;
                        break;
                    }
                }

            }
        }

        return changed
    },

    GetLuaInterfaces: function () {
        return luaInterfaces
    }
}